import {signals,moodLabel} from './v4-world.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>id==='priya'?'Priya':id==='tom'?'Tom':'Tim';
export function liveStrip(w,id){return `<section class="live-world" aria-label="Current world" aria-live="polite"><div class="live-world-heading"><span class="eyebrow">THE WORLD / RIGHT NOW</span><span>Changes with your decisions</span></div><div class="live-world-grid">${signals(w,id).map(s=>`<div class="world-signal ${s.tone}"><span>${s.label}</span><strong>${esc(s.value)}</strong><i aria-hidden="true"></i></div>`).join('')}</div></section>`;}
export function moodPortrait(id,p){return `<div class="portrait mood-portrait small ${id} mood-${p.mood}" aria-hidden="true"><div class="portrait-head"><i class="hair"></i><i class="eyes"></i><i class="mouth"></i></div><div class="portrait-body"></div><span class="portrait-initial">${name(id)[0]}</span></div>`;}
export function reactionPanel(w,id){const p=w.people[id];return `<section class="worker-reaction" aria-label="${name(id)}’s reaction"><div>${moodPortrait(id,p)}<span><strong>${name(id)}</strong><small>${moodLabel[p.mood]}</small></span></div><blockquote>${esc(p.quote)}</blockquote></section>`;}
export function crewRoster(w,active){return `<section class="crew-roster" aria-label="People across the warehouse"><span class="eyebrow">PEOPLE ACROSS THE WAREHOUSE</span><div>${['tim','priya','tom'].map(id=>`<button data-action="person" data-person="${id}" class="${active===id?'active':''}" aria-label="Hear from ${name(id)}, ${moodLabel[w.people[id].mood]}">${moodPortrait(id,w.people[id])}<strong>${name(id)}</strong><span>${moodLabel[w.people[id].mood]}</span></button>`).join('')}</div></section>`;}
export function impactPanel(e,ev){return `<section class="impact-panel" aria-label="Effects of your decision"><h3>What the floor feels now</h3>${e.changes.length?`<div class="change-grid">${e.changes.map(c=>`<div class="change-card ${c.tone}"><span>${c.label}</span><p><del>${esc(c.before)}</del><span aria-hidden="true">→</span><strong>${esc(c.after)}</strong></p></div>`).join('')}</div>`:''}${reactionPanel(ev.world,ev.chapter)}${e.ripples.length?`<div class="ripple-arrived"><span class="eyebrow">AN EARLIER DECISION REACHES THE FLOOR</span>${e.ripples.map(r=>`<p>${esc(r)}</p>`).join('')}</div>`:''}<p class="next-cause"><strong>What this sets up</strong><br>${esc(e.nextReason)}</p></section>`;}
export function developing(w){return w.pending.length?`<section class="developing-world"><span class="eyebrow">STILL MOVING THROUGH THE SHIFT</span>${w.pending.map(p=>`<p>${esc(p.label)}</p>`).join('')}</section>`:'';}
